INSERT INTO device_timelines (device_id, user_id, event_type, event_date, title, description, payload, created_at) SELECT d.id, d.user_id, 'CREATED', COALESCE(d.purchase_date, (d.created_at AT TIME ZONE 'Asia/Shanghai')::date), CASE WHEN d.purchase_date IS NULL THEN '添加设备' ELSE '购入设备' END, CASE WHEN d.purchase_date IS NULL THEN '设备档案已创建' ELSE '已记录设备购入信息' END, jsonb_build_object('changedFields', ARRAY[]::text[]), d.created_at FROM devices d WHERE d.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM device_timelines t WHERE t.device_id = d.id AND t.event_type = 'CREATED');
